// Разбор вложений: выбираем PDF-расчёт (не пени/поручение/пояснительную), доп-контекст, метаданные.
const item = $input.first();
const bin = item.binary || {};
const keys = Object.keys(bin);
const nameOf = (k) => (bin[k].fileName || k);
const lower = (k) => nameOf(k).toLowerCase();
const isPdf = (k) => (bin[k].mimeType||'').includes('pdf') || lower(k).endsWith('.pdf');
// исключаем явно не-расчёты по имени файла
const EXCLUDE = ['пени','платеж','платёж','поручени','пояснительн','реестр','показан'];
const pdfs = keys.filter(isPdf);
const candidates = pdfs.filter(k => !EXCLUDE.some(w => lower(k).includes(w)));
// предпочитаем «расчёт задолженности»; иначе первый не-исключённый PDF
const preferred = candidates.find(k => lower(k).includes('расч') && lower(k).includes('задолж'));
const calcKey = preferred || candidates[0] || null;
let calc_b64 = null, calc_name = null;
if (calcKey) {
  // getBinaryDataBuffer работает при любом режиме хранения бинарников (in-memory/filesystem/S3)
  const buf = await this.helpers.getBinaryDataBuffer(0, calcKey);
  calc_b64 = buf.toString('base64');
  calc_name = nameOf(calcKey);
}
// прочие вложения (всё, кроме выбранного расчёта) — в доп-контекст
const extras = keys.filter(k => k !== calcKey).map(nameOf);
const j = item.json;
return [{ json: {
  has_calc: !!calc_b64,
  calc_b64, calc_name,
  dop_context: (j.text || j.textPlain || '') + (extras.length ? ('\n[вложения: ' + extras.join(', ') + ']') : ''),
  subject: j.subject || '',
  from: j.from || '',
  messageId: j.messageId || (j.headers && j.headers['message-id']) || '',
  retry: 0
}, binary: bin }];

// Тянем контракты/структуру/схему из репозитория (docs_base_url). Флоу статичен, правки — в .md.
const base = $('Config').first().json.docs_base_url.replace(/\/$/, '');
async function get(p){ return await this.helpers.httpRequest({ url: base + '/' + p, json: false }); }
const [extraction, schema, spec, generation] = await Promise.all([
  get.call(this,'01-extraction-contract.md'),
  get.call(this,'02-manifest-schema.md'),
  get.call(this,'04-spec-type-A.md'),
  get.call(this,'05-generation-contract.md')
]);
const j = $input.first().json;
j.extraction_system = extraction + '\n\n---\n\n' + schema;
j.generation_system = spec + '\n\n---\n\n' + generation;
return [{ json: j, binary: $input.first().binary }];

// Достаём JSON манифеста из ответа Anthropic
const resp = $input.first().json;
let text = (resp.content || []).map(c => c.type === 'text' ? c.text : '').join('\n');
text = text.replace(/```json|```/g, '').trim();
let manifest;
try { manifest = JSON.parse(text); } catch(e) { manifest = { _parse_error: e.message, _raw: text }; }
const carry = $('Load Contracts').first().json;
return [{ json: { manifest, generation_system: carry.generation_system,
  from: carry.from, subject: carry.subject, messageId: carry.messageId, calc_name: carry.calc_name },
  binary: $('Prepare Inputs').first().binary }];

const eq = (a, b, tol) => Math.abs(a - b) <= tol;
const T = { line: 0.05, sum: 1.0, k: 0.01 };
const m = $input.first().json.manifest;
const fails = [];
try {
  const em = m.months.find(x => x.month === m.example_month);
  const f = m.flags;
  const t = m.tariffs.find(x => em.month >= x.date_from.slice(0,7) && em.month <= x.date_to.slice(0,7));
  const mult = t.nds === 'without' ? 1.2 : 1.0;
  if (!eq(em.sum_hvs, em.V_hvs * t.tariff_hvs * mult, T.line)) fails.push('1:ХВС');
  if (em.V_stoki !== em.V_hvs + (f.has_gvs ? em.V_gvs : 0)) fails.push('2:V_stoki');
  if (!eq(em.sum_stoki, em.V_stoki * t.tariff_vo * mult, T.line)) fails.push('3:стоки');
  if (f.has_nvcs) {
    if (!eq(em.sum_nvcs, em.sum_stoki * f.k_coefficient, T.line)) fails.push('4:НВЦС');
    if (!eq(f.k_coefficient, 0.5, T.k) && !eq(f.k_coefficient, 2.5, T.k)) fails.push('4:K');
  }
  if (f.has_p203 && !eq(em.sum_p203, em.sum_stoki * 2, T.line)) fails.push('5:п203');
  let comp = em.sum_hvs + em.sum_stoki + (f.has_nvcs ? em.sum_nvcs : 0) + (f.has_p203 ? em.sum_p203 : 0);
  if (!eq(em.month_total, comp, T.line)) fails.push('6:итог_месяца');
  const sm = m.months.reduce((s, x) => s + x.month_total, 0);
  if (!eq(m.totals.charged, sm, T.sum)) fails.push('7:начислено');
  if (!eq(m.totals.balance, m.totals.charged - m.totals.paid, T.sum)) fails.push('8:остаток');
} catch(e) { fails.push('validator_error:' + e.message); }
const j = $input.first().json;
j.passed = fails.length === 0;
j.fails = fails;
return [{ json: j, binary: $input.first().binary }];

